INSERT INTO `pcra_icra_persyaratan_harus_dipenuhi` VALUES
('PH001','Jenis dan lokasi barrier / partisi penghalang debu sudah direncanakan dan disetujui K3RS'),
('PH002','Minimal 2 (dua) jalur keluar aman sudah diidentifikasi dan dipastikan tidak akan terhalang selama konstruksi'),
('PH003','Rencana kompensasi sistem deteksi kebakaran sudah dikomunikasikan ke IPSRS (misal: penutup detektor sementara selama jam kerja)'),
('PH004','Jumlah dan lokasi penempatan APAR di area proyek sudah direncanakan dan disetujui'),
('PH005','Jadwal sosialisasi kode emergensi RS kepada seluruh pekerja proyek sudah ditetapkan sebelum hari pertama kerja'),
('PH006','Lokasi penyimpanan B3 yang sesuai MSDS sudah diidentifikasi dan disetujui, terpisah dari area pasien'),
('PH007','Jenis APD yang diperlukan sesuai tipe pekerjaan sudah ditentukan dan kontraktor sudah menyanggupi penyediaannya'),
('PH008','Jam kerja konstruksi sudah dikoordinasikan dan disetujui manajemen RS agar tidak mengganggu ketenangan pasien'),
('PH009','Jalur mobilisasi material dan pembuangan debris sudah ditetapkan dan tidak melewati area kritis pasien'),
('PH010','Rencana pemantauan kualitas udara & debu harian sudah disiapkan (wajib untuk Kelas III dan IV)'),
('PH011','Mekanisme pembersihan harian area proyek sebelum pekerja meninggalkan lokasi sudah disepakati dalam kontrak'),
('PH012','Kontraktor sudah memahami, menyetujui, dan menandatangani surat perjanjian kepatuhan K3RS sebelum mobilisasi'),
('PH013','Izin kerja konstruksi (work permit) dari manajemen RS sudah diterbitkan');
